import{_ as i,C as p,o as n,c as A,a4 as r,b as e,w as a,a as d,E as l,a5 as o}from"./chunks/framework.BRzJ4ijD.js";const b=JSON.parse('{"title":"AI 加速器：TPU / NPU / FPGA","description":"","frontmatter":{},"headers":[],"relativePath":"computer-arch/ai-accelerators.md","filePath":"computer-arch/ai-accelerators.md","lastUpdated":1788475713000}'),E={name:"computer-arch/ai-accelerators.md"};function h(P,t,c,u,B,g){const s=p("Mermaid");return n(),A("div",null,[t[5]||(t[5]=r('<h1 id="ai-加速器-tpu-npu-fpga" tabindex="-1">AI 加速器：TPU / NPU / FPGA <a class="header-anchor" href="#ai-加速器-tpu-npu-fpga" aria-label="Permalink to &quot;AI 加速器：TPU / NPU / FPGA&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>GPU 做 AI 的致命伤不是算力不够，而是<strong>能效比</strong>：GPU 约 30% 功耗花在控制逻辑上（分支预测、调度、寄存器重命名），对矩阵乘法来说全是浪费。</li><li>TPU 的核心思想是<strong>脉动阵列（Systolic Array）</strong>：数据像波浪一样流过 MAC 单元阵列，每个周期每个单元都在做乘加，零控制开销。</li><li>当代加速器的军备竞赛本质是对抗<strong>存储墙（Memory Wall）</strong>：模型 &gt;1T 参数，99% 的时间在等权重从显存搬过来。Cerebras 的激进答案是整张晶圆做芯片（WSE-3），44GB 片上 SRAM，21 PB/s 带宽，模型不离开芯片。</li><li>Groq LPU 走了另一条路：完全确定性计算，编译器在编译期就排好了每个数据在每个周期的位置——没有缓存、没有分支预测、没有乱序执行。</li><li>ASIC（TPU）有最高能效和峰值算力，FPGA 有最低延迟和可重配置性，CPU（AMX）有最强的通用性。三者不是替代关系，是<strong>异构计算</strong>的拼图。</li><li>最大的护城河不是硬件，是<strong>软件生态</strong>：CUDA 做了 15 年，这也是为什么 Intel Gaudi 硬件不差但市场份额微乎其微。</li></ul><hr><h2 id="_1-为什么不能只用-gpu" tabindex="-1">1. 为什么不能只用 GPU？ <a class="header-anchor" href="#_1-为什么不能只用-gpu" aria-label="Permalink to &quot;1. 为什么不能只用 GPU？&quot;">​</a></h2><p>要回答&quot;Why not just GPUs?&quot;，先看一组数据（H100 SXM，FP8）：</p><table tabindex="0"><thead><tr><th>指标</th><th>数值</th></tr></thead><tbody><tr><td>峰值算力</td><td>1979 TFLOPS</td></tr><tr><td>内存带宽</td><td>3.35 TB/s</td></tr><tr><td>TDP</td><td>700W</td></tr><tr><td>晶体管</td><td>80B</td></tr></tbody></table><p>75 行 Python 启动一次 GEMM，调用栈是：Python → PyTorch → cuBLAS → CUDA Driver → 指令调度 → Tensor Core。GPU 为了通用性付出了巨大的控制开销：warp scheduler、dispatch unit、L0 指令缓存、scoreboard、分支发散处理。这些东西对矩阵乘法没有用，但它们占着面积，烧着功耗。</p><p>粗略估算：一张 H100 上约 30% 的面积和功耗花在非计算逻辑上。对于训练 GPT-4 级模型（几万张 GPU 跑几个月），这 30% 意味着上千万美元的电费和额外的散热基建。</p>',9)),(n(),e(o,null,{default:a(()=>[l(s,{id:"mermaid-97",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20GPU%5B%22GPU%EF%BC%88%E9%80%9A%E7%94%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CU%5B%22CUDA%20Cores%20%2F%20Tensor%20Cores%22%5D%0A%20%20%20%20%20%20%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E9%80%BB%E8%BE%91%EF%BC%88~30%25%20%E5%8A%9F%E8%80%97%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CACHE%5B%22L1%20%2F%20L2%20Cache%22%5D%0A%20%20%20%20%20%20%20%20SCHED%5B%22Warp%20Scheduler%20%2F%20Dispatch%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20ACCEL%5B%22AI%20%E5%8A%A0%E9%80%9F%E5%99%A8%EF%BC%88%E4%B8%93%E7%94%A8%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20MATMUL%5B%22%E5%A4%A7%E8%A7%84%E6%A8%A1%E7%9F%A9%E9%98%B5%E4%B9%98%E6%B3%95%E9%98%B5%E5%88%97%22%5D%0A%20%20%20%20%20%20%20%20SMALL_CTL%5B%22%E6%9E%81%E7%AE%80%E6%8E%A7%E5%88%B6%EF%BC%88~5%25%20%E5%8A%9F%E8%80%97%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20SRAM%5B%22%E5%A4%A7%E5%AE%B9%E9%87%8F%E7%89%87%E4%B8%8A%20SRAM%20%2F%20HBM%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GPU%20--%3E%7C%22%E8%83%BD%E6%95%88%E6%AF%94%E5%B7%AE%22%7C%20WASTE%5B%22%E5%A4%A7%E9%87%8F%E5%8A%9F%E8%80%97%E5%9C%A8%E9%9D%9E%E8%AE%A1%E7%AE%97%E8%B7%AF%E5%BE%84%22%5D%0A%20%20%20%20ACCEL%20--%3E%7C%22%E8%83%BD%E6%95%88%E6%AF%94%E4%BC%98%22%7C%20EFF%5B%22~95%25%20%E5%8A%9F%E8%80%97%E7%94%A8%E4%BA%8E%20MAC%20%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[6]||(t[6]=r(`<p><strong>结论：用 GPU 训练大模型不是&quot;最优解&quot;，是&quot;先用着最方便的解&quot;。</strong> CUDA 生态让 NVIDIA 成为唯一可行的选择，但这不等于 GPU 在硬件上是为 AI 而生的。</p><hr><h2 id="_2-脉动阵列-tpuv1-的心脏" tabindex="-1">2. 脉动阵列：TPUv1 的心脏 <a class="header-anchor" href="#_2-脉动阵列-tpuv1-的心脏" aria-label="Permalink to &quot;2. 脉动阵列：TPUv1 的心脏&quot;">​</a></h2><h3 id="_2-1-什么是脉动阵列-systolic-array" tabindex="-1">2.1 什么是脉动阵列（Systolic Array） <a class="header-anchor" href="#_2-1-什么是脉动阵列-systolic-array" aria-label="Permalink to &quot;2.1 什么是脉动阵列（Systolic Array）&quot;">​</a></h3><p>想象一个 256×256 的网格，每个格子是一个 MAC（Multiplier-Accumulator）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Iteration 0:    Iteration 1:    Iteration 2:</span></span>
<span class="line"><span>┌─┬─┬─┐        ┌─┬─┬─┐        ┌─┬─┬─┐</span></span>
<span class="line"><span>│w│ │ │        │ │w│ │        │ │ │w│</span></span>
<span class="line"><span>├─┼─┼─┤        ├─┼─┼─┤        ├─┼─┼─┤</span></span>
<span class="line"><span>│a│ │ │   →    │ │a│ │   →    │ │ │a│</span></span>
<span class="line"><span>├─┼─┼─┤        ├─┼─┼─┤        ├─┼─┼─┤</span></span>
<span class="line"><span>│ │7│ │        │ │ │8│        │ │ │ │95</span></span>
<span class="line"><span>└─┴─┴─┘        └─┴─┴─┘        └─┴─┴─┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>左：输入激活  右：部分和    上：权重</span></span>
<span class="line"><span>每个格子 = MAC(a_in, w_in, sum_in) → (a_out, sum_out)</span></span></code></pre></div><p>数据流动规则：</p><ul><li><strong>权重从上往下</strong>流动（提前预加载）</li><li><strong>输入激活从左往右</strong>流动</li><li><strong>部分和从上往下</strong>累积</li></ul><p>256 个周期后，整个矩阵乘法结果从底部流出。整个过程<strong>没有寄存器写回冲突、没有缓存未命中、没有任何控制流指令</strong>。</p><h3 id="_2-2-tpuv1-规格-google-2015-年发表" tabindex="-1">2.2 TPUv1 规格（Google，2015 年发表） <a class="header-anchor" href="#_2-2-tpuv1-规格-google-2015-年发表" aria-label="Permalink to &quot;2.2 TPUv1 规格（Google，2015 年发表）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>脉动阵列尺寸</td><td>256 × 256 MAC</td></tr><tr><td>总 MAC 单元数</td><td>65,536</td></tr><tr><td>单周期操作数</td><td>65536 multiply-adds</td></tr><tr><td>峰值算力</td><td>92 TFLOPS（INT8）</td></tr><tr><td>频率</td><td>700 MHz</td></tr><tr><td>片上缓冲</td><td>28 MB SRAM（权重） + 24 MB SRAM（激活）</td></tr><tr><td>片外内存</td><td>8 GB DDR3-2133</td></tr><tr><td>内存带宽</td><td>34 GB/s</td></tr><tr><td>TDP</td><td>~75W</td></tr><tr><td>工艺</td><td>28nm</td></tr><tr><td>编程接口</td><td>TensorFlow（直接下推 XLA 编译的图）</td></tr></tbody></table><p>关键限制：v1 只能推理，不能训练（只有 INT8 计算，没有反向传播所需的高精度梯度累积）。</p>`,12)),(n(),e(o,null,{default:a(()=>[l(s,{id:"mermaid-243",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20HOST%5B%22Host%20CPU%22%5D%20--%3E%7C%22XLA%20%E7%BC%96%E8%AF%91%E5%90%8E%E7%9A%84%E5%AD%90%E5%9B%BE%22%7C%20PCIe%0A%20%20%20%20PCIe%5B%22PCIe%20Gen3%20%C3%9716%22%5D%20--%3E%20DDR3%5B%228%20GB%20DDR3%3Cbr%2F%3E%E6%9D%83%E9%87%8D%E5%AD%98%E5%82%A8%22%5D%0A%20%20%20%20DDR3%20--%3E%20WB%5B%22Weight%20FIFO%3Cbr%2F%3E28%20MB%20SRAM%22%5D%0A%20%20%20%20MMU%5B%22%E6%BF%80%E6%B4%BB%E8%BE%93%E5%85%A5%3Cbr%2F%3E24%20MB%20SRAM%22%5D%20--%3E%20SYST%5B%22256%C3%97256%20Systolic%20Array%3Cbr%2F%3E65536%20MAC%20%40%20700MHz%22%5D%0A%20%20%20%20WB%20--%3E%20SYST%0A%20%20%20%20SYST%20--%3E%20ACC%5B%22Accumulators%3Cbr%2F%3E4%20MB%2C%2032-bit%22%5D%0A%20%20%20%20ACC%20--%3E%20ACT%5B%22Activation%20Unit%3Cbr%2F%3EReLU%2FReLU6%2FTanh%2FSigmoid%22%5D%0A%20%20%20%20ACT%20--%3E%20MMU%5B%22%E5%86%99%E5%9B%9E%20Unified%20Buffer%22%5D%0A"})]),fallback:a(()=>[...t[1]||(t[1]=[d(" Loading... ",-1)])]),_:1})),t[7]||(t[7]=r('<p>TPUv1 仅需一个 PCIe 插槽，功耗 75W，在当时（2015）性能远超同功耗的 GPU 推理。</p><hr><h2 id="_3-tpuv4-v5-的演进" tabindex="-1">3. TPUv4 / v5 的演进 <a class="header-anchor" href="#_3-tpuv4-v5-的演进" aria-label="Permalink to &quot;3. TPUv4 / v5 的演进&quot;">​</a></h2><h3 id="_3-1-tpuv4-2021" tabindex="-1">3.1 TPUv4（2021） <a class="header-anchor" href="#_3-1-tpuv4-2021" aria-label="Permalink to &quot;3.1 TPUv4（2021）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>峰值算力</td><td>275 TFLOPS（BF16）</td></tr><tr><td>片上 HBM</td><td>32 GB HBM2e</td></tr><tr><td>内存带宽</td><td>1.2 TB/s</td></tr><tr><td>单芯片 TDP</td><td>~200W</td></tr><tr><td>Pod 规模</td><td>4096 芯片</td></tr><tr><td>Pod 算力</td><td>1.1 EFLOPS（BF16）</td></tr><tr><td>互联拓扑</td><td><strong>光电路交换（OCS）</strong>——动态可重构</td></tr></tbody></table><p>TPUv4 的创新在于<strong>光电路交换（Optical Circuit Switching）</strong>。传统 GPU 集群的拓扑是固定的（如 NVIDIA DGX 的 NVSwitch + NVLink 全互联），而 TPUv4 可以通过 MEMS 镜片动态改变芯片间的连接拓扑，使得不同训练阶段（数据并行 vs 模型并行 vs 流水线并行）可以使用最优的互联拓扑。</p>',6)),(n(),e(o,null,{default:a(()=>[l(s,{id:"mermaid-327",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20Pod%5B%22TPUv4%20Pod%20%E2%80%94%204096%20%E8%8A%AF%E7%89%87%22%5D%0A%20%20%20%20%20%20%20%20R1%5B%22Rack%201%3Cbr%2F%3E64%20chips%22%5D%20---%20OCS1%5B%22Optical%20Circuit%3Cbr%2F%3ESwitch%201%22%5D%0A%20%20%20%20%20%20%20%20R2%5B%22Rack%202%3Cbr%2F%3E64%20chips%22%5D%20---%20OCS2%5B%22Optical%20Circuit%3Cbr%2F%3ESwitch%202%22%5D%0A%20%20%20%20%20%20%20%20OCS1%20---%20OCS2%0A%20%20%20%20%20%20%20%20OCS1%20---%20OCS3%5B%22OCS%203%22%5D%0A%20%20%20%20%20%20%20%20OCS2%20---%20OCS3%0A%20%20%20%20end%0A%20%20%20%20Pod%20---%20TOR%5B%22Spine%20%2F%20ToR%3Cbr%2F%3E%E5%8F%AF%E5%8A%A8%E6%80%81%E9%85%8D%E7%BD%AE%E6%8B%93%E6%89%91%22%5D%0A"})]),fallback:a(()=>[...t[2]||(t[2]=[d(" Loading... ",-1)])]),_:1})),t[8]||(t[8]=r(`<h3 id="_3-2-tpuv5p-2023" tabindex="-1">3.2 TPUv5p（2023） <a class="header-anchor" href="#_3-2-tpuv5p-2023" aria-label="Permalink to &quot;3.2 TPUv5p（2023）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>峰值算力</td><td>459 TFLOPS（BF16）/ 918 TFLOPS（INT8）</td></tr><tr><td>片上 HBM</td><td>95 GB HBM2e</td></tr><tr><td>关键新特性</td><td><strong>SparseCore</strong>——硬件加速的嵌入查找</td></tr><tr><td>每 Pod 芯片</td><td>8960</td></tr><tr><td>Pod 算力</td><td>4.1 EFLOPS（BF16）</td></tr></tbody></table><p>Google 用 TPUv5p 训练 Gemini 系列模型。值得注意：Bard / Gemini 的推理也大量运行在 TPUv5e 上（&quot;e&quot; 表示推理优化版）。</p><hr><h2 id="_4-sparsecore-嵌入查找的硬件加速" tabindex="-1">4. SparseCore：嵌入查找的硬件加速 <a class="header-anchor" href="#_4-sparsecore-嵌入查找的硬件加速" aria-label="Permalink to &quot;4. SparseCore：嵌入查找的硬件加速&quot;">​</a></h2><h3 id="_4-1-问题" tabindex="-1">4.1 问题 <a class="header-anchor" href="#_4-1-问题" aria-label="Permalink to &quot;4.1 问题&quot;">​</a></h3><p>推荐系统（YouTube、TikTok）和 MoE（Mixture of Experts）模型的核心操作是<strong>大稀疏矩阵乘法</strong>——嵌入表查找。举个具体例子：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>YouTube 推荐模型：10 million items × 1024 dim embedding = 10 GB 嵌入表</span></span>
<span class="line"><span>每次 query：只访问 ~100 个 item（即稀疏访问 100 行）</span></span>
<span class="line"><span>GPU 操作：gather → matmul → scatter  （内存不连续 → 带宽利用率极低）</span></span></code></pre></div><p>GPU 的 <code>gather</code> 指令在这里效率极差。HBM 的峰值带宽只有在<strong>连续访问、128B 对齐</strong>时才打得满，而嵌入查找天生是随机的、步长不等的。</p><h3 id="_4-2-sparsecore-方案" tabindex="-1">4.2 SparseCore 方案 <a class="header-anchor" href="#_4-2-sparsecore-方案" aria-label="Permalink to &quot;4.2 SparseCore 方案&quot;">​</a></h3><p>TPUv4 之后，Google 在芯片上放了专用的 SparseCore：一个小型的、高带宽的嵌入查找加速器。SparseCore 有自己的 SRAM 缓存和硬件 scatter/gather 引擎，能同时做：</p><ol><li><strong>嵌入查找</strong>：根据索引从表中取值</li><li><strong>规约</strong>：将查到的向量进行 reduce（sum / mean / concat）</li><li><strong>与稠密部分汇合</strong>：将稀疏结果传给主 Systolic Array</li></ol><p>效果：推荐模型训练/推理的嵌入查找部分加速了 <strong>5-7 倍</strong>。</p><hr><h2 id="_5-数据流架构-cerebras-wse-3" tabindex="-1">5. 数据流架构：Cerebras WSE-3 <a class="header-anchor" href="#_5-数据流架构-cerebras-wse-3" aria-label="Permalink to &quot;5. 数据流架构：Cerebras WSE-3&quot;">​</a></h2><p>WSE（Wafer-Scale Engine）的哲学跟所有其他芯片相反：<strong>既然数据传输消耗 99% 的能量，那就让数据别动了。</strong></p><h3 id="_5-1-规格" tabindex="-1">5.1 规格 <a class="header-anchor" href="#_5-1-规格" aria-label="Permalink to &quot;5.1 规格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>晶体管</td><td>4 万亿</td></tr><tr><td>AI 核心数</td><td>900,000</td></tr><tr><td>片上 SRAM</td><td>44 GB</td></tr><tr><td>片上带宽</td><td>21 PB/s</td></tr><tr><td>芯片面积</td><td>46,225 mm²（整张 300mm 晶圆）</td></tr><tr><td>功耗</td><td>23 kW（整片）</td></tr><tr><td>工艺</td><td>5nm（TSMC）</td></tr><tr><td>内存</td><td><strong>无片外 DRAM</strong>——所有数据在片上</td></tr></tbody></table><p>对比 H100：片外 HBM3 带宽 3.35 TB/s vs WSE-3 片上 21 PB/s。差距是 6000 倍。但这 44GB SRAM 也意味着模型必须完整装进去——GPT-4 的 1.7T 参数完全不可能。Cerebras 的目标场景是：<strong>科学计算、分子动力学、流体力学的稀疏/规则网格计算</strong>，以及中等规模的 LLM（如 LLaMA 2 7B）的极致训练速度。</p>`,19)),(n(),e(o,null,{default:a(()=>[l(s,{id:"mermaid-519",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20TRAD%5B%22%E4%BC%A0%E7%BB%9F%E6%9E%B6%E6%9E%84%EF%BC%88GPU%20%2F%20TPU%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20CORE1%5B%22%E8%AE%A1%E7%AE%97%E6%A0%B8%E5%BF%83%22%5D%20---%7C%22~3%20TB%2Fs%22%7C%20HBM%5B%22HBM%20%E6%98%BE%E5%AD%98%22%5D%0A%20%20%20%20%20%20%20%20HBM%20---%7C%22~1%20TB%2Fs%22%7C%20CORE2%5B%22%E5%8F%A6%E4%B8%80%E6%A0%B8%E5%BF%83%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20WSE%5B%22Cerebras%20WSE-3%EF%BC%88%E6%95%B0%E6%8D%AE%E6%B5%81%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20TILE1%5B%22Tile%201%3Cbr%2F%3EMAC%20%2B%20SRAM%22%5D%20---%7C%22%E7%89%87%E4%B8%8A%E4%BA%92%E8%81%94%3Cbr%2F%3E21%20PB%2Fs%22%7C%20TILE2%5B%22Tile%202%3Cbr%2F%3EMAC%20%2B%20SRAM%22%5D%0A%20%20%20%20%20%20%20%20TILE2%20---%20TILE3%5B%22Tile%203%3Cbr%2F%3EMAC%20%2B%20SRAM%22%5D%0A%20%20%20%20%20%20%20%20TILE1%20---%20TILE3%0A%20%20%20%20end%0A%0A%20%20%20%20TRAD%20-.-%7C%22%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90%E8%83%BD%E8%80%97%20%3E%20%E8%AE%A1%E7%AE%97%E8%83%BD%E8%80%97%22%7C%20BAD%5B%22~99%25%20%E8%83%BD%E9%87%8F%E8%8A%B1%E5%9C%A8%E6%95%B0%E6%8D%AE%E6%90%AC%E8%BF%90%22%5D%0A%20%20%20%20WSE%20-.-%7C%22%E6%95%B0%E6%8D%AE%E4%B8%8D%E5%8A%A8%EF%BC%8C%E7%AE%97%E5%8A%9B%E5%8A%A8%22%7C%20GOOD%5B%22%E8%83%BD%E9%87%8F%E5%87%A0%E4%B9%8E%E5%85%A8%E7%94%A8%E4%BA%8E%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...t[3]||(t[3]=[d(" Loading... ",-1)])]),_:1})),t[9]||(t[9]=r(`<hr><h2 id="_6-groq-lpu-确定性处理器" tabindex="-1">6. Groq LPU：确定性处理器 <a class="header-anchor" href="#_6-groq-lpu-确定性处理器" aria-label="Permalink to &quot;6. Groq LPU：确定性处理器&quot;">​</a></h2><p>Groq 的创始人 Jonathan Ross 也是 TPU 的创始人之一。LPU（Language Processing Unit）的设计理念是<strong>极致确定性</strong>。</p><h3 id="_6-1-核心设计" tabindex="-1">6.1 核心设计 <a class="header-anchor" href="#_6-1-核心设计" aria-label="Permalink to &quot;6.1 核心设计&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统处理器（CPU/GPU）：</span></span>
<span class="line"><span>    程序→取指→译码→调度→执行→缓存未命中→等待→写回</span></span>
<span class="line"><span>    每一步都有不确定性（缓存命中率、分支方向、执行端口竞争）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Groq LPU：</span></span>
<span class="line"><span>    编译器在编译期就排好了：</span></span>
<span class="line"><span>      - 每个数据在第几个周期到达哪个功能单元</span></span>
<span class="line"><span>      - 每个算术操作的结果去向哪个 SRAM 地址</span></span>
<span class="line"><span>      - 每次片间通信的精确时序</span></span>
<span class="line"><span>    硬件上：零缓存、零分支预测、零乱序执行、零 scoreboard</span></span></code></pre></div><h3 id="_6-2-架构" tabindex="-1">6.2 架构 <a class="header-anchor" href="#_6-2-架构" aria-label="Permalink to &quot;6.2 架构&quot;">​</a></h3><p>Groq 的芯片由 <strong>Functional Slice</strong> 组成，排列成一个 2D 网格。每个 Slice 包含：</p><ul><li>一个 SIMD 向量计算单元（16 条通道 × 32 位）</li><li>一块本地 SRAM</li><li>一个路由单元（与四方邻居通信）</li></ul><p><strong>软件定义网络（Software-Defined Network）</strong>：编译器把每个数据流映射成芯片上的一条路径，数据从 SRAM→SIMD→路由→邻居→路由→...→目标 SRAM，全部在编译期确定。</p><h3 id="_6-3-规格" tabindex="-1">6.3 规格 <a class="header-anchor" href="#_6-3-规格" aria-label="Permalink to &quot;6.3 规格&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>片上 SRAM</td><td>230 MB</td></tr><tr><td>内存带宽</td><td>80 TB/s</td></tr><tr><td>峰值 INT8</td><td>188 TFLOPS</td></tr><tr><td>峰值 FP16</td><td>94 TFLOPS</td></tr><tr><td>TDP</td><td>~300W</td></tr><tr><td>工艺</td><td>7nm</td></tr></tbody></table><p>Groq 的目标场景是 LLM 推理（所以叫 Language Processing Unit）。Llama 2 70B 推理可以达到 ~300 tokens/s/用户。核心卖点：<strong>延迟可预测性和极端内存带宽</strong>（80 TB/s 远超 H100 的 3.35 TB/s）。</p><hr><h2 id="_7-apple-neural-engine-ane" tabindex="-1">7. Apple Neural Engine（ANE） <a class="header-anchor" href="#_7-apple-neural-engine-ane" aria-label="Permalink to &quot;7. Apple Neural Engine（ANE）&quot;">​</a></h2><p>从 A11 Bionic（2017，iPhone 8/X）开始，每代 A 系列和 M 系列芯片都包含一个独立的 ANE。</p><table tabindex="0"><thead><tr><th>SoC</th><th>年份</th><th>ANE 规格</th><th>TOPS (INT8)</th></tr></thead><tbody><tr><td>A11</td><td>2017</td><td>2 核</td><td>0.6</td></tr><tr><td>A12</td><td>2018</td><td>8 核</td><td>5</td></tr><tr><td>A13</td><td>2019</td><td>8 核</td><td>6</td></tr><tr><td>A14</td><td>2020</td><td>16 核</td><td>11</td></tr><tr><td>A15</td><td>2021</td><td>16 核</td><td>15.8</td></tr><tr><td>A16</td><td>2022</td><td>16 核</td><td>17</td></tr><tr><td>A17 Pro</td><td>2023</td><td>16 核</td><td>35</td></tr><tr><td>M4</td><td>2024</td><td>16 核</td><td>38</td></tr></tbody></table><p><strong>架构特点：</strong></p><ul><li>ANE 是独立于 CPU/GPU 的硬件模块，有自己的 DMA 引擎和内存空间</li><li>支持几十种 CoreML 算子（卷积、池化、归一化、激活函数）</li><li><strong>无公开低层 API</strong>——所有开发必须通过 CoreML 框架（Apple 统一编译到 ANE）</li><li>功耗极低：A17 Pro 的 ANE 满载约 2W，同性能功耗 GPU 需要约 15W</li><li>应用场景：Face ID、实时照片处理、键盘预测、Siri 本地处理</li></ul><p><strong>关键设计取舍：</strong> Apple 牺牲了通用可编程性来换取极致能效比。你不能在 ANE 上跑自定义 CUDA kernel，但 iPhone 上 99% 的 ML 任务已经被 CoreML 覆盖。</p><hr><h2 id="_8-qualcomm-hexagon-npu" tabindex="-1">8. Qualcomm Hexagon NPU <a class="header-anchor" href="#_8-qualcomm-hexagon-npu" aria-label="Permalink to &quot;8. Qualcomm Hexagon NPU&quot;">​</a></h2><p>Hexagon 不是新产品线——Qualcomm 做 Hexagon DSP 已经超过 15 年。但 Hexagon NPU（从 Snapdragon 8 Gen 1 开始）是全新架构。</p><p>Snapdragon 8 Gen 3 的 <strong>AI Engine</strong> 是一个融合结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──────────────────────────────┐</span></span>
<span class="line"><span>                │  Snapdragon 8 Gen 3 AI Engine  │</span></span>
<span class="line"><span>                ├──────────────────────────────┤</span></span>
<span class="line"><span>                │  Hexagon NPU（Transformer 加速）│</span></span>
<span class="line"><span>                │  + Adreno GPU（通用 ML）        │</span></span>
<span class="line"><span>                │  + Kryo CPU（标量 / 控制流）     │</span></span>
<span class="line"><span>                │  + Sensing Hub（超低功耗感知）    │</span></span>
<span class="line"><span>                └──────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>峰值 INT4</td><td>45 TOPS</td></tr><tr><td>峰值 INT8</td><td>22.5 TOPS</td></tr><tr><td>支持</td><td>LLaMA 2 7B（INT4 量化，纯本地运行）</td></tr><tr><td>编程</td><td>Qualcomm AI Engine Direct SDK / Qualcomm AI Hub</td></tr></tbody></table><p>关键能力：<strong>在整个 SoC 上分配 ML 算子</strong>。Transformer 的 Attention 跑在 NPU 上，LayerNorm 跑在 CPU 上，量化/去量化跑在 GPU 上。高通的异构调度器自动决定每个算子的最优硬件。</p><hr><h2 id="_9-intel-amx-cpu-里的张量核心" tabindex="-1">9. Intel AMX：CPU 里的张量核心 <a class="header-anchor" href="#_9-intel-amx-cpu-里的张量核心" aria-label="Permalink to &quot;9. Intel AMX：CPU 里的张量核心&quot;">​</a></h2><p>Sapphire Rapids（第 4 代 Xeon 可扩展，2023）引入了 <strong>AMX</strong>（Advanced Matrix Extensions）。</p><h3 id="_9-1-架构" tabindex="-1">9.1 架构 <a class="header-anchor" href="#_9-1-架构" aria-label="Permalink to &quot;9.1 架构&quot;">​</a></h3><p>AMX 给 x86 增加了<strong>Tile Register</strong>——一组扁平化的、2048 位的二维寄存器文件（8 个 tile 寄存器 × 每 tile 16 行 × 64 字节/行 = 1 KB / tile = 共 8 KB）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>指令集：</span></span>
<span class="line"><span>  TDPBF16PS( tdest, tsrc1, tsrc2 )</span></span>
<span class="line"><span>    // Tile Dot Product BF16 × BF16 → FP32</span></span>
<span class="line"><span>    // 单条指令完成一个 16×16 的 BF16 矩阵乘法</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  TILELOAD / TILESTORE</span></span>
<span class="line"><span>    // 从内存到 tile 寄存器的加载/存储</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  TILERELEASE</span></span>
<span class="line"><span>    // 释放 AMX 状态（上下文切换前必须调用）</span></span></code></pre></div><h3 id="_9-2-性能" tabindex="-1">9.2 性能 <a class="header-anchor" href="#_9-2-性能" aria-label="Permalink to &quot;9.2 性能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>每核/周期</th><th>56 核 @ 2.0 GHz 总计</th></tr></thead><tbody><tr><td>INT8 matmul</td><td>2048 ops</td><td>114.7 TFLOPS</td></tr><tr><td>BF16 matmul</td><td>1024 ops</td><td>57.3 TFLOPS</td></tr></tbody></table><p>本质上，AMX 就是 <strong>&quot;CPU 上的 Tensor Core&quot;</strong>。</p><h3 id="_9-3-为什么-cpu-也要做-ai" tabindex="-1">9.3 为什么 CPU 也要做 AI <a class="header-anchor" href="#_9-3-为什么-cpu-也要做-ai" aria-label="Permalink to &quot;9.3 为什么 CPU 也要做 AI&quot;">​</a></h3><p>两件事驱动：</p><ol><li><strong>推理不必都在 GPU</strong>：很多推理任务是突发小批量（如 API 服务），GPU 启动延迟就几十微秒。CPU 上没有 kernel launch 开销，对微小 batch 反而更快。</li><li><strong>数据中心 CPU 本来就插满了</strong>：如果 CPU 就能跑推理，不需要额外的 GPU 采购、供电、冷却。</li></ol><p>Intel 的策略不是替代 GPU，而是让 Xeon 可处理&quot;GPU 太浪费、普通 CPU 太慢&quot;的中间地带工作负载。</p><hr><h2 id="_10-fpga-在-ml-推理中的角色" tabindex="-1">10. FPGA 在 ML 推理中的角色 <a class="header-anchor" href="#_10-fpga-在-ml-推理中的角色" aria-label="Permalink to &quot;10. FPGA 在 ML 推理中的角色&quot;">​</a></h2><h3 id="_10-1-为什么用-fpga" tabindex="-1">10.1 为什么用 FPGA？ <a class="header-anchor" href="#_10-1-为什么用-fpga" aria-label="Permalink to &quot;10.1 为什么用 FPGA？&quot;">​</a></h3><p>FPGA 的独特优势不是峰值算力，而是：</p><table tabindex="0"><thead><tr><th>维度</th><th>GPU / TPU</th><th>FPGA</th></tr></thead><tbody><tr><td>延迟</td><td>微秒级（kernel launch + 调度）</td><td>纳秒级（无 OS 内核开销）</td></tr><tr><td>大批量效率</td><td>高（利用所有算力）</td><td>中（流水线深度有限）</td></tr><tr><td>小批量效率</td><td>差（批次填不满 Tensor Core）</td><td>优（pipeline 可以浅）</td></tr><tr><td>可重配置</td><td>否</td><td>是（烧一个新比特流）</td></tr><tr><td>开发难度</td><td>CUDA/PyTorch</td><td>HLS / Verilog</td></tr><tr><td>单芯片 TOPS</td><td>极高</td><td>中低</td></tr></tbody></table><h3 id="_10-2-代表性产品" tabindex="-1">10.2 代表性产品 <a class="header-anchor" href="#_10-2-代表性产品" aria-label="Permalink to &quot;10.2 代表性产品&quot;">​</a></h3><p><strong>Microsoft Project Brainwave（2018）</strong></p><ul><li>目标：Azure 上实时 DNN 推理（&lt; 1ms 延迟）</li><li>硬件：Intel Stratix 10 FPGA + HBM2</li><li>架构：软核 DNN 处理器，无批量处理（batch=1 也是满吞吐）</li><li>结果：ResNet-50 推理 450K QPS @ &lt; 1ms，2018 年业界最优</li><li>关键创新：FPGA 上直接做浮点运算矩阵乘法，数据从 HBM → LUT/DSP → 结果，没有软件栈</li></ul><p><strong>Xilinx（AMD）Versal AI Engine</strong></p><ul><li>架构：VLIW SIMD 处理器阵列（不是传统 LUT 逻辑）</li><li>每个 AI Engine：32KB 本地数据 + 512-bit SIMD</li><li>互联：AXI4-Stream，软件可重配数据流</li><li>性能：VC1902 约 180 TFLOPS INT8（FPGA 中最高）</li><li>编程：AI Engine 用 C++ kernel，编译器做时空映射</li></ul><h3 id="_10-3-fpga-的困局" tabindex="-1">10.3 FPGA 的困局 <a class="header-anchor" href="#_10-3-fpga-的困局" aria-label="Permalink to &quot;10.3 FPGA 的困局&quot;">​</a></h3><p>FPGA 理论上优雅：为算法定制电路。现实中三个问题：</p><ol><li><strong>编程门槛极高</strong>：CUDA 程序员一抓一把，HLS/Verilog 工程师少得多</li><li><strong>单芯片算力仍低于 GPU/TPU</strong>：ASIC 能用晶体管极致优化一种计算，FPGA 必须用通用 LUT 模拟一切</li><li><strong>每芯片贵、大批量部署不如 ASIC 经济</strong></li></ol><p>FPGA 的最佳生态位：<strong>超低延迟推理</strong>（自驾驶感知、量化交易）和<strong>定制算子加速</strong>（SmartNIC 上的 ML 处理、5G 基站内的 AI）。</p><hr><h2 id="_11-存储墙-所有加速器的共同敌人" tabindex="-1">11. 存储墙：所有加速器的共同敌人 <a class="header-anchor" href="#_11-存储墙-所有加速器的共同敌人" aria-label="Permalink to &quot;11. 存储墙：所有加速器的共同敌人&quot;">​</a></h2>`,55)),(n(),e(o,null,{default:a(()=>[l(s,{id:"mermaid-1123",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E8%A7%84%E6%A8%A1%EF%BC%9A%E6%AF%8F%20~2%20%E5%B9%B4%2010%C3%97%22%5D%20--%3E%20GAP%5B%22%E8%AE%A1%E7%AE%97%20vs%20%E5%B8%A6%E5%AE%BD%E5%A2%9E%E9%80%9F%E8%90%BD%E5%B7%AE%22%5D%0A%20%20%20%20BANDWIDTH%5B%22%E5%86%85%E5%AD%98%E5%B8%A6%E5%AE%BD%EF%BC%9A%E6%AF%8F%20~2%20%E5%B9%B4%201.5%C3%97%22%5D%20--%3E%20GAP%0A%0A%20%20%20%20GAP%20--%3E%20WALL%5B%22%E5%AD%98%E5%82%A8%E5%A2%99%EF%BC%88Memory%20Wall%EF%BC%89%22%5D%0A%0A%20%20%20%20WALL%20--%3E%20SOL1%5B%22HBM%EF%BC%9A%E5%A0%86%E5%8F%A0%20DRAM%3Cbr%2F%3E%E5%B8%A6%E5%AE%BD%20~3.35%20TB%2Fs%EF%BC%88H100%EF%BC%89%22%5D%0A%20%20%20%20WALL%20--%3E%20SOL2%5B%22%E7%89%87%E4%B8%8A%20SRAM%EF%BC%9AWSE-3%3Cbr%2F%3E21%20PB%2Fs%EF%BC%8C%E4%BD%86%E5%AE%B9%E9%87%8F%E4%BB%85%2044GB%22%5D%0A%20%20%20%20WALL%20--%3E%20SOL3%5B%22%E9%87%8F%E5%8C%96%EF%BC%9AFP8%20%2F%20INT4%3Cbr%2F%3E%E6%AF%8F%E6%AC%A1%E5%B0%91%E6%90%AC%202-4%C3%97%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20%20%20WALL%20--%3E%20SOL4%5B%22%E6%A8%A1%E5%9E%8B%E5%B9%B6%E8%A1%8C%EF%BC%9A%E5%88%87%E5%88%86%E5%88%B0%E5%A4%9A%E8%8A%AF%E7%89%87%3Cbr%2F%3E%E6%AF%8F%E8%8A%AF%E7%89%87%E4%BB%85%E9%9C%80%E8%87%AA%E5%B7%B1%E7%9A%84%E5%8F%82%E6%95%B0%E5%AD%90%E9%9B%86%22%5D%0A%20%20%20%20WALL%20--%3E%20SOL5%5B%22%E5%AD%98%E5%86%85%E8%AE%A1%E7%AE%97%EF%BC%88PIM%20%2F%20NDP%EF%BC%89%3Cbr%2F%3E%E5%9C%A8%20DRAM%20%E5%86%85%E9%83%A8%E7%9B%B4%E6%8E%A5%E8%AE%A1%E7%AE%97%22%5D%0A"})]),fallback:a(()=>[...t[4]||(t[4]=[d(" Loading... ",-1)])]),_:1})),t[10]||(t[10]=r(`<p><strong>具体估算：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GPT-4 推理（推测 ~1.7T 参数，FP16）：</span></span>
<span class="line"><span>  模型大小 = 1.7 × 10^12 × 2 bytes = 3.4 TB</span></span>
<span class="line"><span>  H100 带宽 = 3.35 TB/s</span></span>
<span class="line"><span>  纯搬运时间 = 3.4 / 3.35 ≈ 1 秒 / token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  实际 GPU 集群用 8 张 H100：</span></span>
<span class="line"><span>  每张 8 / 3.35 ≈ 2.4 秒（需等待，不能并行读取所有参数）</span></span>
<span class="line"><span>  实际还要算 FLOPs，但瓶颈仍是带宽。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Token 生成速度 ≈ 内存带宽 / 模型大小（首近似）</span></span></code></pre></div><p>这就是为什么量化（INT4/FP8）是推理优化的第一优先级：直接把数据量砍 4 倍，延迟砍 4 倍。</p><hr><h2 id="_12-加速器对比总表" tabindex="-1">12. 加速器对比总表 <a class="header-anchor" href="#_12-加速器对比总表" aria-label="Permalink to &quot;12. 加速器对比总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>加速器</th><th>峰值算力</th><th>内存带宽</th><th>功耗</th><th>工艺</th><th>定位</th></tr></thead><tbody><tr><td>NVIDIA H100</td><td>1979 TFLOPS (FP8)</td><td>3.35 TB/s (HBM3)</td><td>700W</td><td>4nm / TSMC</td><td>训练 + 推理（CUDA）</td></tr><tr><td>Google TPUv5p</td><td>459 TFLOPS (BF16)</td><td>~2.7 TB/s (HBM2e)</td><td>~450W</td><td>5nm</td><td>Gemini 训练 + 推理</td></tr><tr><td>Cerebras WSE-3</td><td>~100 PFLOPS (BF16)</td><td>21 PB/s (片上 SRAM)</td><td>23 kW</td><td>5nm / TSMC</td><td>科学计算 + 中等 LLM</td></tr><tr><td>Groq LPU</td><td>188 TFLOPS (INT8)</td><td>80 TB/s (片上 SRAM)</td><td>~300W</td><td>7nm</td><td>LLM 推理（确定性延迟）</td></tr><tr><td>Apple ANE (A17)</td><td>35 TOPS (INT8)</td><td>共享 LPDDR5</td><td>~2W</td><td>3nm / TSMC</td><td>端侧推理（CoreML）</td></tr><tr><td>Intel AMX (8480+)</td><td>57 TFLOPS (BF16)</td><td>DDR5 共享</td><td>350W</td><td>Intel 7</td><td>中等批量 CPU 推理</td></tr><tr><td>AMD Versal VP1902</td><td>~180 TOPS (INT8)</td><td>~1.6 TB/s</td><td>~120W</td><td>7nm</td><td>实时推理 / 信号处理</td></tr><tr><td>Qualcomm Hexagon</td><td>45 TOPS (INT4)</td><td>共享 LPDDR5X</td><td>~5W</td><td>4nm / TSMC</td><td>手机端 LLM</td></tr></tbody></table><blockquote><p>注意：<strong>峰值 TOPS 不等于实际吞吐</strong>。同样 TOPS 的不同硬件，实际利用率可能差 2-3 倍。Cerebras 和 Groq 靠片上 SRAM 能达到 70-80% 利用率，GPU 在大部分工作负载下仅 30-50%。</p></blockquote><hr><h2 id="_13-工程案例" tabindex="-1">13. 工程案例 <a class="header-anchor" href="#_13-工程案例" aria-label="Permalink to &quot;13. 工程案例&quot;">​</a></h2><h3 id="_13-1-project-brainwave-微软-2018" tabindex="-1">13.1 Project Brainwave（微软，2018） <a class="header-anchor" href="#_13-1-project-brainwave-微软-2018" aria-label="Permalink to &quot;13.1 Project Brainwave（微软，2018）&quot;">​</a></h3><ul><li><strong>挑战</strong>：Azure 上的实时 AI 服务要求 &lt;1ms 延迟。GPU 的 kernel launch + batch 累积有几十微秒的不可控延时。</li><li><strong>方案</strong>：用 Intel Stratix 10 FPGA，直接在硬件上实现 DNN 推理。无 CPU 调度、无 kernel 启动，数据流直通。</li><li><strong>成果</strong>：ResNet-50 推理延迟 &lt;1ms（batch=1），单 FPGA 吞吐 450K QPS，Azure 大规模采用。</li><li><strong>启示</strong>：对超低延迟推理，FPGA 可能比 GPU 和 TPU 都好——不是算力大，是延迟可控。</li></ul><h3 id="_13-2-habana-gaudi-intel-2019-2024" tabindex="-1">13.2 Habana Gaudi（Intel，2019-2024） <a class="header-anchor" href="#_13-2-habana-gaudi-intel-2019-2024" aria-label="Permalink to &quot;13.2 Habana Gaudi（Intel，2019-2024）&quot;">​</a></h3><p>Intel 收购 Habana 后推出的训练加速器：</p><ul><li><strong>硬件不差</strong>：Gaudi2 在 ResNet-50/ BERT 训练上与 A100 打平甚至超出</li><li><strong>互联强</strong>：每个 Gaudi2 芯片集成 24 个 100GbE RoCE 端口，专为大规模 Scale-out 设计</li><li><strong>实际问题</strong>：<strong>软件兼容性</strong>。PyTorch 的 <code>torch.compile</code> 和底层 CUDA kernel 是 15 年的积累，Gaudi 的 SynapseAI 软件栈需要逐算子适配。到 2024 年仍有很多模型无法无缝迁移。</li><li><strong>教训</strong>：AI 加速器的护城河 80% 在软件生态。</li></ul><hr><h2 id="_14-易错清单" tabindex="-1">14. 易错清单 <a class="header-anchor" href="#_14-易错清单" aria-label="Permalink to &quot;14. 易错清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误认知</th><th>正确理解</th></tr></thead><tbody><tr><td>&quot;TOPS 越高越快&quot;</td><td>峰值 TOPS 仅代表所有 MAC 单元同时工作的理论上限。实际性能取决于<strong>内存带宽</strong>和<strong>软件映射效率</strong>。H100 的 1979 TFLOPS 在大部分 Transformer 训练中利用率仅 40-50%。</td></tr><tr><td>&quot;FPGA 总是比 GPU 功耗低&quot;</td><td>取决于场景。做同样的矩阵乘法吞吐，FPGA 需要更多 LUT/DSP 资源，整体功耗可能反而高于类似工艺的 ASIC（如 TPU）。FPGA 的功率优势体现在对<strong>特定小工作负载</strong>的极致优化。</td></tr><tr><td>&quot;买个加速器就能加速模型&quot;</td><td>加速器的软件栈成熟度直接决定上线周期。CUDA 生态 15 年积累 vs 新硬件仅支持 PyTorch 基础算子。自研模型（自定义 attention、特殊激活函数）可能完全无法在非 NVIDIA 硬件上运行。</td></tr><tr><td>&quot;片上 SRAM 大就是好&quot;</td><td>容量和速度是 trade-off。Cerebras WSE-3 的 44GB SRAM 虽然带宽极高，但装不下 70B+ 的大模型，必须走模型并行。Groq 230MB SRAM 对 LLM 70B 也需要数百张卡拼接。</td></tr><tr><td>&quot;TPU 比 GPU 好，Google 不用 GPU&quot;</td><td>Google 内部同时使用 TPU（主力）和 GPU（匹配公有云客户需求）。2024 年 Google Cloud 提供 A3 实例（H100）和 TPUv5e 实例，两种都商用。</td></tr><tr><td>&quot;AI 加速器会取代 GPU&quot;</td><td>不会。GPU 的通用性在处理非 ML 工作负载（图形渲染、科学仿真、视频编解码）时仍有不可替代性。正确的问题是&quot;什么工作负载跑在什么硬件上最优&quot;，而不是找一个通用答案。</td></tr></tbody></table><hr><h2 id="_15-这一章带走的东西" tabindex="-1">15. 这一章带走的东西 <a class="header-anchor" href="#_15-这一章带走的东西" aria-label="Permalink to &quot;15. 这一章带走的东西&quot;">​</a></h2><ol><li><strong>能效是 AI 加速器存在的理由，不是算力</strong>：GPU 够快但太费电。专用硬件把 30% 控制开销降到 5%，省下的就是真金白银。</li><li><strong>脉动阵列是 AI 加速器的基础范式</strong>：TPUv1 就已验证，后来几乎所有 NPU（包括 Google TPU、AWS Trainium、华为昇腾）都采用类似的 Systolic Array 乘加结构。</li><li><strong>存储墙是当前的头号瓶颈</strong>：模型规模增速（~10×/2年）远快于内存带宽增速（~1.5×/2年）。对抗存储墙的手段包括 HBM 堆叠、片上 SRAM、量化、模型并行和存内计算。</li><li><strong>异构计算是终端侧的必然</strong>：手机上的 AI 不是只跑在 NPU 上——高通、苹果、联发科全都在做&quot;NPU + GPU + CPU + DSP&quot;异构调度。未来没有哪个芯片能单独解决所有 ML 问题。</li><li><strong>软件生态 &gt; 硬件指标</strong>：这是 AI 加速器行业 10 年来最重要的教训。Intel Gaudi、AMD Instinct、Cerebras CS-3 的硬件都不差，但没有一个能真正撼动 NVIDIA + CUDA 的组合。硬件可以 18 个月追上，软件生态需要 10 年。</li><li><strong>FPGA 和 ASIC 不是竞争，是分工</strong>：ASIC（TPU 等）做大批量、高吞吐的云端训练/推理；FPGA 做超低延迟、小批量、可重配置的边缘场景。</li></ol><hr><blockquote><p><strong>下一节 → <a href="./interconnects">总线与互联：PCIe / CXL / NVLink / RDMA</a></strong> 如何把成千上万个加速器连起来组成一个训练集群？PCIe 带宽为什么不够用了？CXL 怎么把内存池化？RDMA 如何让 GPU 直接写对端 GPU 的 HBM？下一章讲互联总线。</p></blockquote>`,22))])}const T=i(E,[["render",h]]);export{b as __pageData,T as default};
